import copy
import json
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
references = json.loads(Path('reference-targets.json').read_text())
answers = copy.deepcopy(json.loads(Path('previous-answer.json').read_text()))
by_number = {a['number']: a for a in answers}
targets = references['targets']
target_by_number = {v['number']: k for k, v in targets.items()}

# Conserver les articles complets du précédent essai et leurs corrections valides.
# Les vérifications des renvois sont toutes reconstruites après lecture des vues actuelles.
for a in answers:
    a.pop('reference_checks', None)

a = by_number['R6222-6']
old = "Sous réserve des prolongations et dérogations prévues aux articles L. 6222-11, L. 6222-12-1, R. 6222-9 et R. 6222-23-1 ainsi que des aménagements visés au 2° de l'article L. 6222-37 et au 1° de l'article L. 6222-40, la durée ainsi fixée ne peut être inférieure à six mois ni supérieure à trois ans."
new = "Sous réserve des prolongations et réductions légalement applicables, des dérogations prévues à l'article R. 6222-23-1 et des aménagements visés au 2° de l'article L. 6222-37 et au 1° de l'article L. 6222-40, la durée ainsi fixée ne peut être inférieure à six mois ni supérieure à trois ans. La dispense de convention prévue à l'article R. 6222-9 demeure applicable."
assert old in a['proposed_xml']
a['proposed_xml'] = a['proposed_xml'].replace(old, new)
a['reason'] = "Les corrections de l'essai précédent sont conservées : renvoi au troisième alinéa de L. 6222-7-1, convention pouvant figurer dans un support commun signé, annexe légale et évaluation pertinente maintenues. Après confrontation avec la cible actuelle entière, la loi proposée exige encore l'annexe : sa suppression ne peut être tenue pour acquise par ce règlement. Les nouvelles références numérotées à L. 6222-11 et L. 6222-12-1 sont retirées sans supprimer leurs prolongations ou réductions légales ; les dispenses de R. 6222-9 sont expressément réservées. Aucun nouvel allègement autonome n'est compté pour la seule faculté de support commun. Les bornes générales protègent la consistance de la formation, tandis que les régimes favorables conservent leurs propres règles."
a['review_notes'] = "Cibles actuelles lues intégralement : le troisième alinéa de L. 6222-7-1 fixe l'accord tripartite et son annexe ; le dernier alinéa de sa proposition est désormais transitoire. Le support commun ne dispense donc ni d'accord ni d'annexion de la partie utile. Les premier, deuxième et troisième alinéas de R. 6222-6 gardent respectivement l'évaluation, les bornes pédagogiques et la signature adaptée au CFA interne. La réserve du deuxième alinéa ne crée pas de nouvelle convention dans les cas dispensés par R. 6222-9 ou R. 6222-23-1. Les 2° de L. 6222-37 et 1° de L. 6222-40 portent seulement sur les durées adaptées, et non sur toutes les obligations des personnes handicapées ou des sportifs. L. 6222-11 et L. 6222-12-1, sources et notes lues dans le corpus public, permettent respectivement la prolongation d'un an au plus après échec et la réduction des mois de formation avant embauche, celle-ci pouvant commencer trois mois au plus sans employeur. Leurs nouveaux renvois numérotés sont retirés du texte proposé ; ces règles restent couvertes par la réserve des prolongations et réductions légales et par R. 6222-9. Aucun renvoi à L. 6353-1 n'est ajouté. La convention reste un accord pédagogique ; elle ne renouvelle ni un CDD, ni un essai, ni l'ancienneté. La suppression du modèle obligatoire est portée par R. 6222-7, sans double compte de réduction. Aucune coupe supplémentaire de l'évaluation ou du consentement n'est retenue, car ils fondent l'adaptation individuelle et sa preuve."

a = by_number['R6222-21']
old = "les mesures des articles L. 6225-4 et L. 6225-5"
new = "les mesures de suspension avec maintien de la rémunération et de rupture protectrice en cas de risque sérieux d'atteinte à la santé ou à l'intégrité physique ou morale de l'apprenti, avec leurs indemnités spéciales,"
assert old in a['proposed_xml']
a['proposed_xml'] = a['proposed_xml'].replace(old, new)
# La computation propre à l'essai ne doit pas imposer la forme du licenciement.
needle = "Le préavis ne prolonge pas l'essai."
replacement = "En cas de rupture de l'essai par l'employeur, les quinze jours calendaires se comptent à partir du lendemain de la réception par le salarié de la notification, faite par tout moyen permettant d'établir cette réception. Le préavis ne prolonge pas l'essai."
assert needle in a['proposed_xml']
a['proposed_xml'] = a['proposed_xml'].replace(needle, replacement)
needle = "La fin d'une formation ou l'obtention d'un diplôme ne rompt pas automatiquement l'emploi."
replacement = "La faute grave ne supprime pas le préavis patronal ; si elle rend impossible le maintien au travail, le préavis est payé sans être exécuté. La fin d'une formation ou l'obtention d'un diplôme ne rompt pas automatiquement l'emploi."
assert needle in a['proposed_xml']
a['proposed_xml'] = a['proposed_xml'].replace(needle, replacement)
a['reason'] = "La fusion des deux communications en un envoi au CFA et un relais de celui-ci est conservée, avec sa tâche institutionnelle de remplacement explicitement recensée. Le texte garde le préavis du contrat unique, son départ au lendemain, les mois complets pour l'indemnité, le seuil au terme effectif et les protections spéciales. La computation propre à l'essai est précisée sans lui imposer la forme du licenciement. Les nouveaux renvois numérotés à L. 6225-4 et L. 6225-5, absents des cibles fournies, sont retirés ; les mesures protectrices et leurs indemnités restent expressément réservées. Ni les quinze jours ni le barème commun ne sont comptés comme une baisse universelle par rapport aux ruptures spéciales de la source."
a['review_notes'] = "L. 6222-18, source, note et proposition actuelles entières : la source prévoit quarante-cinq jours de pratique, puis accord écrit ou cas particuliers de rupture, médiation, garanties du mineur et liquidation. Sa note exclut déjà les contrats conclus avant le 1er janvier 2019 ; la réserve des versions applicables préserve aussi ces contrats plus anciens. Pour les nouveaux contrats de droit privé, la proposition cible applique le contrat unique et renvoie à L. 1234-9 sous ses conditions, sans reconduire le terme pédagogique. L. 1234-9 actuel proposé exclut l'indemnité ordinaire en cas de faute grave mais non les droits spéciaux ; L. 1234-1 proposé conserve alors le préavis patronal payé sans exécution. Le calcul porte sur toute l'ancienneté reconnue, mois complets au prorata, seuil d'un an au terme effectif, préavis exécuté ou non inclus sous réserve de la fin d'essai, plafond légal de six mois distinct des indemnités plus favorables. Les sources et propositions de L. 1234-3, L. 1221-25, R. 1234-1 et D. 6222-21-1 ont été lues dans le corpus public sans ajout d'un renvoi normatif vers ces cibles non fournies : lendemain de réception pour l'essai, reliquat patronal compensé sans prolonger l'essai ni l'ancienneté, et absence de cumul des anciennes attentes de cinq puis sept jours pour les nouveaux contrats. L. 6222-19, source entière lue, reste une faculté de départ sur diplôme après information de l'employeur, jamais une fin automatique ; les dispenses favorables demeurent réservées. L. 6225-4 et L. 6225-5 ont été lus intégralement : suspension avec salaire, décision de reprise sous quinze jours et rupture sur refus avec sommes liées à la période restante constituent une protection spéciale distincte du barème ordinaire. Leurs nouveaux renvois numérotés sont retirés et leurs effets sont réservés expressément dans le texte ; ces deux articles ne sont pas réécrits ici. L. 6227-1 lu : un employeur public peut conclure un contrat d'apprentissage ; le critère est donc la nature de la relation, non la seule identité publique de l'employeur. Les agents publics ne sont pas assimilés aux salariés privés ; la médiation sectorielle et les garanties du représentant légal subsistent. Le relais CFA doit être organisé sans nouveau dossier ni remise à zéro des notifications déjà valables. Les compétences de suspension et autorisations ainsi que les procédures collectives ne sont pas supprimées. Le présent raccordement réglementaire suppose l'entrée en vigueur des dispositions législatives proposées ; il ne les fait pas passer pour le droit en vigueur. Aucun audit juridique indépendant ni solde net de coûts n'est affirmé."
a['substantive_impact']['new_burdens_review'] += " L'essai de trois mois, seulement s'il est expressément stipulé et sans renouvellement, remplace le régime légal des quarante-cinq jours pratiques pour l'emploi nouveau ; ses effets de durée ne sont pas uniformes selon l'alternance et ne sont pas présentés comme une réduction générale."
a['substantive_impact']['effects'].append({
    'kind': 'coordination',
    'measure_id': 'contrat-unique-essai-trois-mois',
    'description': "Raccordement de l'essai d'apprentissage au régime commun proposé, sans compter une baisse uniforme de sa durée.",
    'before': "Renvoi au régime de rupture de L. 6222-18, dont la source ouvre une rupture par chaque partie pendant quarante-cinq jours de formation pratique, consécutifs ou non.",
    'after': "Essai expressément stipulé de trois mois sans renouvellement pour le nouvel emploi ; préavis de quinze jours sans prolongation de l'essai et compensation du reliquat patronal.",
    'unit': 'regime',
    'affected_population': "Apprentis et employeurs des nouveaux contrats uniques de droit privé comportant un essai.",
    'conditions_and_transition': "Contrats nouveaux après l'entrée en vigueur ; pas de nouvel essai lié à une phase pédagogique ou mission ; anciens contrats sous leur régime applicable.",
    'replacement_or_new_burdens': "Condition de stipulation expresse et préavis commun ; la durée calendaire ne se compare pas uniformément à quarante-cinq jours de pratique alternée. Solde net non établi.",
    'source_quote': "dans les conditions prévues aux articles L. 6222-18 à L. 6222-19.",
    'proposed_quote': "Lorsqu'un essai est expressément stipulé pour le nouveau contrat, il est de trois mois sans renouvellement",
})

a = by_number['D6123-37']
a['review_notes'] = "L. 6131-1 et L. 6242-1 figurent désormais parmi les cibles fournies ; leurs sources, notes et propositions actuelles ont été lues en entier. Le I, 4°, de L. 6131-1 réserve le CPF-CDD aux périodes de travail antérieures à l'entrée en vigueur, même si un ancien CDD se poursuit ; son I, 3°, et le I de L. 6242-1 suppriment la contribution supplémentaire à l'apprentissage seulement pour les années commençant le 1er janvier suivant l'entrée en vigueur de sa loi de suppression. Les deux calendriers ne sont pas fusionnés. Le quotient de 5 %, les catégories du II et les règles d'effectif du V de L. 6242-1 restent utiles à la créance du solde de taxe d'apprentissage ; l'aide au recrutement et les droits futurs restent expressément réservés par son VIII. Le présent circuit ne doit donc transmettre ni assiette, ni montant, ni état néant de contribution supprimée pour une année nouvelle, tout en conservant dans ses catégories existantes les données nécessaires à ces avantages et aux années anciennes. Aucune liste annuelle de nouveaux redevables ne peut être reconstituée. Le I, 5°, de L. 6131-1 concerne les contributions conventionnelles distinctes, qui demeurent. Les enquêtes du 14° de L. 6123-5 ne sont pas abrogées ; seule leur alimentation obligatoire par ce circuit est retirée. R. 6123-34, source et note lues dans le corpus public, conserve son objet de tables de correspondance sans nouvelle collecte créée ici. L. 6323-20-1, lu intégralement avec sa note, concerne le CPF des salariés de personnes publiques et ne définit pas de cotisation autonome : l'incohérence préexistante de ce renvoi source reste signalée, sans correction silencieuse ni assiette inventée. Le nom commercial est retiré car l'identifiant d'établissement et la raison sociale suffisent à l'identification dans ce circuit ; les effectifs d'alternants et de bénéficiaires handicapés, périodes d'activité et masses salariales demeurent pour l'affectation des fonds, les prises en charge et les missions conservées des opérateurs. Aucun nouvel accès aux données ni nouvelle déclaration d'entreprise ne résulte de ces réserves. Le réemploi légal ne démontre pas un gain supplémentaire par rapport au CRPA. Les rubriques DSN et textes d'exécution restent à coordonner ; ils ne sont pas réputés réécrits."

a = by_number['D6222-1']
a['review_notes'] += " La cible actuelle L. 6222-18 traite l'inaptitude constatée par le médecin du travail mais ne définit pas une procédure autonome de constat d'inaptitude temporaire : l'articulation déjà elliptique du 4° source reste à contrôler. Le renvoi est conservé sans inventer de certificat médical ni importer aux admissions nouvelles les quarante-cinq jours de formation pratique. La note de L. 6222-2 exclut déjà les contrats antérieurs au 1er janvier 2019 ; les droits d'admission antérieurs restent protégés dans leur version applicable."

